FROM (
  SELECT
    (SELECT COUNT(*) FROM Patient WHERE SEX='F') AS total_females,
    (SELECT COUNT(DISTINCT p.ID)
     FROM Patient p
     JOIN Laboratory l ON p.ID = l.ID
     WHERE p.SEX='F' AND l.UA > 6.5
    ) AS high_count
);

