  SELECT
    (SELECT COUNT(DISTINCT ID) FROM Patient WHERE SEX='F') AS tot,
    (SELECT COUNT(DISTINCT l.ID) FROM Laboratory l JOIN Patient p ON l.ID = p.ID WHERE p.SEX='F' AND l.UA > 6.5) AS beyond
);

