WITH num AS (
  SELECT COUNT(DISTINCT ym.CustomerID) AS cnt
  FROM yearmonth ym
  JOIN customers cu ON ym.CustomerID = cu.CustomerID
  WHERE cu.Segment = 'LAM' AND ym.Consumption > 46.73
), den AS (
  SELECT COUNT(*) AS cnt FROM customers WHERE Segment = 'LAM'
)
SELECT CASE WHEN den.cnt = 0 THEN 0.0 ELSE (num.cnt * 100.0) / den.cnt END AS percent
FROM num, den;

